"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["75189"],{7410(e){e.exports=JSON.parse('{"id":"V4-100","slug":"floating-rate-note","term":"Floating-Rate Note","also_known_as":[],"difficulty":"Intermediate","definition":"A floating-rate note (FRN) is a bond whose interest rate is not fixed but resets periodically, usually every three or six months, based on a benchmark interest rate plus a fixed margin.","explanation":["The coupon on a floating-rate note moves with market interest rates. For example, an FRN might pay SOFR plus 0.75%. If SOFR is 4%, the coupon is 4.75%; if SOFR falls to 3%, the coupon falls to 3.75%.","Because the coupon adjusts, the price of an FRN stays close to its face value, so it carries much less interest rate risk than a fixed-rate bond. Its price changes mainly if the issuer\u2019s credit quality changes.","FRNs are issued by banks, companies and governments. They appeal to investors who expect interest rates to rise or who want to limit interest rate risk, such as money market funds and banks matching floating-rate liabilities.","The trade-off is that income falls when interest rates fall. FRNs still carry the issuer\u2019s credit risk. Since the end of LIBOR, most new floating-rate notes reference overnight benchmark rates, such as SOFR in the United States and SONIA in the United Kingdom, usually compounded over each interest period."],"note":"","total":1725,"prev":{"slug":"floating-exchange-rate","term":"Floating Exchange Rate"},"next":{"slug":"football-field-chart","term":"Football Field Chart"}}')}}]);